-- data_014_limpieza_calles_prefijo_duplicado.sql
-- Problema detectado: el usuario reporto en el front nombres de calle mostrados como
-- "Calle Calle X" (tipo_vialidad duplicado). Se confirmo que es un problema de DATOS,
-- no del backend ni del front: 336 + 2182 registros de `calles`
-- (en su mayoria importados por OSM en las migraciones 009/010) tienen el campo `nombre`
-- con el tipo de vialidad ya incluido como texto (ej. nombre="Calle Esteban Baca Calderon",
-- tipo_vialidad="Calle"), a diferencia de la convencion usada en el resto del catalogo
-- (INEGI, migraciones 011/013) donde `nombre` NUNCA incluye el tipo. El front arma la
-- etiqueta como `${tipo_vialidad} ${nombre}`, por lo que estas filas se mostraban duplicadas.
--
-- Ademas se detecto que, para 2182 de esas filas, ya existia una fila
-- "limpia" (sin el prefijo) representando la MISMA calle real (ej. "Calle La Yesca" y
-- "La Yesca" coexistian como 2 registros separados) porque el constraint unico
-- (`uk_calles_nombre_normalizado`) compara el texto normalizado literal, y "calle la yesca"
-- y "la yesca" son cadenas distintas aunque representen la misma calle. Estos casos se
-- fusionan: se migran sus relaciones en `calles_colonias` hacia la fila canonica (limpia)
-- y se desactivan (activo=0, NUNCA se borran) las filas duplicadas.
-- Generado 2026-08-25T04:30:09.485Z

START TRANSACTION;

